endpoints.typescript_example:
// Record a repeated exposure  (permissions: imaging.order.update)
export const recordRepeat = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/repeats`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// The register of repeated images  (permissions: imaging.order.update, diagnostics.quality.view)
export const listRepeats = () =>
  api("GET", `/imaging/repeats`, undefined);   // api(): see get_guide('envelope-and-errors')

